import React from "react";
import {Box,styled} from '@mui/material';
const Heading = styled(Box)`background: #000080`

const Editor = ()=>{
    return(
        <Box>
           <Box>
            <Heading>
                <Box component="span" 
                style={{
                    background:'red',
                    height:'20px',width:'20px',
                    display:'flex',
                    placeContent:'center',
                    borderRadius:'5px',
                    marginRight:'5px',
                    paddingBottom:'2px'}}>/

                </Box>
                Code
            </Heading>

           </Box>
        </Box>

    )
}

export default Editor;
